.hidden { display: none !important; }

footer { width: min(1180px, calc(100% - 32px)); margin: 60px auto 0; padding: 24px 0 38px; display: flex; justify-content: space-between; border-top: 1px solid var(--line); color: var(--muted); font-size: 11px; }

