const store = $getWorkflowStaticData('global');
store.jobs = store.jobs || {};
store.tasks = store.tasks || {};
store.queue = store.queue || [];
store.processFinals = store.processFinals || {};

const jobId = String(($json.query || {}).job_id || '');
const current = store.jobs[jobId];
const snapshot = store.processFinals[jobId];
const processTask = store.tasks['process-' + jobId];
const taskFinal = processTask?.final_result && typeof processTask.final_result === 'object'
  ? processTask.final_result
  : null;

function hasDecisionPayload(value) {
  return Boolean(
    value
    && value.decision
    && typeof value.decision === 'object'
    && String(value.decision.decision || '').trim()
  );
}

function isProcessTerminal(value) {
  const status = String(value?.status || '').toUpperCase();
  return ['AWAITING_CONFIRMATION', 'NEEDS_RETAKE', 'COMPLETED'].includes(status);
}

const finalCandidate = [snapshot, taskFinal]
  .filter(value => value && typeof value === 'object')
  .sort((a, b) => {
    const aRich = Number(isProcessTerminal(a)) + Number(hasDecisionPayload(a));
    const bRich = Number(isProcessTerminal(b)) + Number(hasDecisionPayload(b));
    if (aRich !== bRich) return bRich - aRich;
    const aTime = Date.parse(a.worker_final_at || a.updated_at || a.created_at || 0) || 0;
    const bTime = Date.parse(b.worker_final_at || b.updated_at || b.created_at || 0) || 0;
    return bTime - aTime;
  })[0] || null;

if (!current && !finalCandidate) {
  return [{ json: { status: 'ERROR', error: 'Job not found.', detail: 'Job not found.' } }];
}

const currentStatus = String(current?.status || '').toUpperCase();

// Confirmation/completion state is newer than the PROCESS result. Preserve it,
// but merge the PROCESS final underneath so decision/images remain available
// after a confirmation error.
if (['CONFIRMING', 'COMPLETED', 'ERROR'].includes(currentStatus)) {
  if (finalCandidate && currentStatus === 'CONFIRMING') {
    return [{ json: { ...finalCandidate, ...current, job_id: jobId } }];
  }
  return [{ json: current }];
}

// For processing/terminal-pre-confirmation states, the rich worker-final
// snapshot wins over any lightweight progress object that may still be visible.
if (finalCandidate && isProcessTerminal(finalCandidate) && hasDecisionPayload(finalCandidate)) {
  return [{ json: {
    ...(current || {}),
    ...finalCandidate,
    job_id: jobId,
    served_from_worker_final: true,
  } }];
}

// Self-heal jobs created by the older workflow. If the browser can see a
// terminal status but no decision and no durable final snapshot exists, requeue
// the SAME PROCESS task at most three times. The local /jobs/from-r2 endpoint is
// idempotent for an existing job: it returns the existing local state, after
// which the worker immediately fetches /jobs/{id}/links and republishes the rich
// final payload. This recovers the already-stuck job without re-running YOLO.
if (
  current
  && ['AWAITING_CONFIRMATION', 'NEEDS_RETAKE'].includes(currentStatus)
  && !hasDecisionPayload(current)
  && !finalCandidate
  && processTask
  && processTask.payload
) {
  const processTaskStatus = String(processTask.status || '').toUpperCase();
  const repairAttempts = Number(processTask.result_sync_repair_attempts || 0);
  const now = Date.now();
  const lastRepair = Number(processTask.result_sync_repair_queued_at || 0);
  const repairCooldownMs = 60 * 1000;

  if (
    processTaskStatus === 'COMPLETED'
    && repairAttempts < 3
    && (!lastRepair || now - lastRepair >= repairCooldownMs)
  ) {
    processTask.status = 'QUEUED';
    processTask.leased_at = 0;
    processTask.leased_by = '';
    processTask.updated_at = now;
    processTask.result_sync_repair_attempts = repairAttempts + 1;
    processTask.result_sync_repair_queued_at = now;
    store.queue = store.queue.filter(id => id !== processTask.task_id);
    store.queue.push(processTask.task_id);

    return [{ json: {
      ...current,
      job_id: jobId,
      result_sync_repair_queued: true,
      result_sync_repair_attempt: repairAttempts + 1,
      message: 'AI đã xử lý xong. Đang yêu cầu worker đồng bộ lại payload kết quả đầy đủ.',
    } }];
  }
}

return [{ json: current || finalCandidate }];

const store = $getWorkflowStaticData('global');
store.tasks = store.tasks || {};
store.queue = store.queue || [];
store.jobs = store.jobs || {};

const body = $json.body || {};
const jobId = String(body.job_id || '');
const selectedProductCode = String(body.product_code || '').trim();
const selectedQuantity = body.quantity == null ? null : Number(body.quantity);
const selectedDocumentType = String(body.document_type || 'PURCHASE_RECEIPT').toUpperCase();

if (body.confirm !== true) {
  const detail = 'Explicit confirmation is required.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}

if (!/^[0-9a-f]{32}$/.test(jobId)) {
  const detail = 'Invalid job ID.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}
if (selectedQuantity !== null && (!Number.isInteger(selectedQuantity) || selectedQuantity < 1 || selectedQuantity > 5000)) {
  const detail = 'Confirmed quantity must be an integer between 1 and 5000.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}
if (!['PURCHASE_RECEIPT', 'MANUFACTURING'].includes(selectedDocumentType)) {
  const detail = 'Invalid KiotViet document type.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}

const job = store.jobs[jobId];
if (!job) {
  const detail = 'Job not found.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}

const currentStatus = String(job.status || '').toUpperCase();

if (currentStatus === 'COMPLETED' && job.kiotviet?.created === true) {
  return [{ json: job }];
}

if (currentStatus === 'CONFIRMING') {
  const taskId = 'confirm-' + jobId;
  const existingTask = store.tasks[taskId];
  if (
    existingTask
    && ['QUEUED', 'LEASED'].includes(String(existingTask.status || '').toUpperCase())
  ) {
    return [{ json: job }];
  }

  // The local backend persisted CONFIRMING before calling KiotViet. A retry
  // must reach that backend so it can reconcile by job_id. Re-queueing the
  // same task ID is safe; it does not ask the backend for an unguarded POST.
  const retryPayload = { confirm: true };
  retryPayload.document_type = String(
    job.confirmation?.document_type || job.document_type || 'PURCHASE_RECEIPT',
  ).toUpperCase();
  const confirmedCode = String(job.confirmation?.product_code || '').trim();
  if (confirmedCode) retryPayload.product_code = confirmedCode;
  const confirmedQuantity = Number(job.confirmation?.quantity || 0);
  if (confirmedQuantity > 0) retryPayload.quantity = confirmedQuantity;
  const now = Date.now();
  store.tasks[taskId] = {
    task_id: taskId,
    job_id: jobId,
    task_type: 'CONFIRM',
    payload: retryPayload,
    status: 'QUEUED',
    attempts: 0,
    created_at: now,
    updated_at: now,
  };
  store.queue = store.queue.filter(id => id !== taskId);
  store.queue.push(taskId);
  store.jobs[jobId] = {
    ...job,
    confirmation_error: '',
    updated_at: new Date(now).toISOString(),
  };
  return [{ json: {
    ...store.jobs[jobId],
    message: 'Confirmation reconciliation queued for the outbound AI worker.',
  } }];
}

if (currentStatus !== 'AWAITING_CONFIRMATION') {
  const detail = 'Job is not waiting for confirmation. Current status: ' + currentStatus + '.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}

const decision = job.decision && typeof job.decision === 'object' ? job.decision : {};
const decisionType = String(decision.decision || '').toUpperCase();

if (!['DIRECT', 'FAMILY', 'REVIEW'].includes(decisionType)) {
  const detail = 'Only DIRECT, FAMILY or REVIEW decisions can be confirmed.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}

const taskPayload = { confirm: true, document_type: selectedDocumentType };
if (selectedQuantity !== null) taskPayload.quantity = selectedQuantity;

// The operator UI intentionally allows correcting DIRECT / FAMILY / REVIEW
// results to "Khác" (another product in the supported catalog).  Validate the
// correction against the job's closed product_catalog instead of restricting
// FAMILY/REVIEW to only the AI suggestions.  This keeps arbitrary product codes
// out while allowing the manual correction flow shown in the UI.
let targetProductCode = selectedProductCode;

if (!targetProductCode && decisionType === 'DIRECT') {
  targetProductCode = String(decision.product_code || '').trim();
}

if (!targetProductCode) {
  const detail = 'Select a supported product before confirming.';
  return [{ json: { status: 'ERROR', error: detail, detail } }];
}

const productCatalog = Array.isArray(job.product_catalog)
  ? job.product_catalog
  : [];

const catalogMatch = productCatalog.find(
  product => String(product?.product_code || '').trim().toLowerCase()
    === targetProductCode.toLowerCase(),
);

if (productCatalog.length) {
  if (!catalogMatch) {
    const detail = 'Selected product is not in the supported product catalog.';
    return [{ json: { status: 'ERROR', error: detail, detail } }];
  }

  // Use the canonical code from the catalog, preserving exact case/spelling.
  taskPayload.product_code = String(catalogMatch.product_code || '').trim();
} else {
  // Backward-compatible fallback for old jobs that were created before
  // product_catalog was included in worker responses.
  let validFallback = false;
  let canonicalFallbackCode = targetProductCode;

  if (decisionType === 'DIRECT') {
    const expectedCode = String(decision.product_code || '').trim();
    validFallback = Boolean(
      expectedCode
      && expectedCode.toLowerCase() === targetProductCode.toLowerCase()
    );
    if (validFallback) canonicalFallbackCode = expectedCode;
  } else if (decisionType === 'FAMILY') {
    const members = Array.isArray(decision.members) ? decision.members : [];
    const member = members.find(
      item => String(item?.product_code || '').trim().toLowerCase()
        === targetProductCode.toLowerCase(),
    );
    validFallback = Boolean(member);
    if (member) canonicalFallbackCode = String(member.product_code || '').trim();
  } else {
    const candidates = Array.isArray(decision.candidates) ? decision.candidates : [];
    const candidate = candidates.find(
      item => String(item?.product_code || '').trim().toLowerCase()
        === targetProductCode.toLowerCase(),
    );
    validFallback = Boolean(candidate);
    if (candidate) canonicalFallbackCode = String(candidate.product_code || '').trim();
  }

  if (!validFallback) {
    const detail = 'This older job has no product catalog; select one of its AI suggestions or run a new job.';
    return [{ json: { status: 'ERROR', error: detail, detail } }];
  }

  taskPayload.product_code = canonicalFallbackCode;
}

const taskId = 'confirm-' + jobId;
const existingTask = store.tasks[taskId];

if (
  existingTask
  && ['QUEUED', 'LEASED'].includes(String(existingTask.status || '').toUpperCase())
) {
  return [{ json: store.jobs[jobId] }];
}

const now = Date.now();
store.tasks[taskId] = {
  task_id: taskId,
  job_id: jobId,
  task_type: 'CONFIRM',
  payload: taskPayload,
  status: 'QUEUED',
  attempts: 0,
  created_at: now,
  updated_at: now,
};
store.queue.push(taskId);

store.jobs[jobId] = {
  ...job,
  status: 'CONFIRMING',
  confirmation: {
    requested_at: new Date(now).toISOString(),
    product_code: taskPayload.product_code || decision.product_code || null,
    quantity: taskPayload.quantity || decision.count || null,
    document_type: taskPayload.document_type,
  },
  document_type: taskPayload.document_type,
  confirmation_error: '',
  updated_at: new Date(now).toISOString(),
};

return [{
  json: {
    ...store.jobs[jobId],
    message: 'Confirmation queued for the outbound AI worker.',
  },
}];

const store = $getWorkflowStaticData('global');
store.tasks = store.tasks || {};
store.queue = store.queue || [];
store.worker = store.worker || {};
const workerId = String(($json.query || {}).worker_id || 'unknown-worker');
const now = Date.now();
const leaseMs = 60 * 60 * 1000;

// A healthy worker polls this endpoint frequently. If it is the currently
// registered worker, let the poll refresh last_seen as a secondary liveness
// signal. This prevents one transient heartbeat failure from making the web UI
// immediately report the worker offline.
if (String(store.worker.worker_id || '') === workerId) {
  store.worker.last_seen_ms = now;
  store.worker.last_seen = new Date(now).toISOString();
}

let selected = null;
for (const taskId of store.queue) {
  const task = store.tasks[taskId];
  if (!task) continue;
  const expired = (
    task.status === 'LEASED'
    && Number(task.leased_at || 0) + leaseMs < now
  );
  if (task.status === 'QUEUED' || expired) {
    task.status = 'LEASED';
    task.leased_at = now;
    task.leased_by = workerId;
    task.attempts = Number(task.attempts || 0) + 1;
    task.updated_at = now;
    selected = { ...task };
    break;
  }
}

// Run maintenance only when the queue is idle, never inside the heartbeat or
// a result-report path. Keep the sweep bounded so it cannot monopolize an n8n
// webhook execution if static data has grown large.
if (!selected && Number(store.last_cleanup_ms || 0) + 60 * 60 * 1000 < now) {
  store.requests = store.requests || {};
  store.jobs = store.jobs || {};
  store.processFinals = store.processFinals || {};
  store.developerRequests = store.developerRequests || {};

  const taskCutoff = now - 24 * 60 * 60 * 1000;
  const jobCutoff = now - 30 * 24 * 60 * 60 * 1000;
  const cleanupBudget = 500;
  let removed = 0;

  for (const [id, task] of Object.entries(store.tasks)) {
    if (removed >= cleanupBudget) break;
    if (
      ['COMPLETED', 'ERROR'].includes(String(task.status || '').toUpperCase())
      && Number(task.updated_at || 0) < taskCutoff
    ) {
      delete store.tasks[id];
      removed += 1;
    }
  }

  for (const [id, request] of Object.entries(store.requests)) {
    if (removed >= cleanupBudget) break;
    const updated = Date.parse(request.updated_at || request.created_at || 0);
    if (Number.isFinite(updated) && updated < taskCutoff) {
      delete store.requests[id];
      removed += 1;
    }
  }

  for (const [id, job] of Object.entries(store.jobs)) {
    if (removed >= cleanupBudget) break;
    const updated = Date.parse(job.updated_at || job.created_at || 0);
    if (
      ['COMPLETED', 'ERROR'].includes(String(job.status || '').toUpperCase())
      && Number.isFinite(updated)
      && updated < jobCutoff
    ) {
      delete store.jobs[id];
      removed += 1;
    }
  }

  for (const [id, snapshot] of Object.entries(store.processFinals)) {
    if (removed >= cleanupBudget) break;
    const updated = Date.parse(snapshot.worker_final_at || snapshot.updated_at || snapshot.created_at || 0);
    if (Number.isFinite(updated) && updated < jobCutoff) {
      delete store.processFinals[id];
      removed += 1;
    }
  }

  for (const [id, request] of Object.entries(store.developerRequests)) {
    if (removed >= cleanupBudget) break;
    const updated = Date.parse(request.updated_at || request.created_at || 0);
    if (Number.isFinite(updated) && updated < taskCutoff) {
      delete store.developerRequests[id];
      removed += 1;
    }
  }

  store.queue = store.queue.filter(
    id => store.tasks[id]
      && !['COMPLETED', 'ERROR'].includes(
        String(store.tasks[id].status || '').toUpperCase(),
      ),
  );

  // If the budget was exhausted, make another idle cleanup eligible in ~5 min;
  // otherwise wait the normal hour.
  store.last_cleanup_ms = removed >= cleanupBudget
    ? now - 55 * 60 * 1000
    : now;
}

return [{ json: { task: selected } }];

const store = $getWorkflowStaticData('global');
store.tasks = store.tasks || {};
store.queue = store.queue || [];
store.requests = store.requests || {};
store.jobs = store.jobs || {};
store.processFinals = store.processFinals || {};
store.worker = store.worker || {};
store.developerRequests = store.developerRequests || {};

const body = $json.body || {};
const taskId = String(body.task_id || '');
const task = store.tasks[taskId];
if (!task) return [{ json: { ok: false, detail: 'Task not found.' } }];

const result = body.result && typeof body.result === 'object' ? body.result : {};
const ok = body.ok === true;
const final = body.final === true;
const error = String(body.error || result.error || '');
const now = Date.now();
const nowIso = new Date(now).toISOString();
const taskType = String(task.task_type || '').toUpperCase();

function hasDecisionPayload(value) {
  return Boolean(
    value
    && value.decision
    && typeof value.decision === 'object'
    && String(value.decision.decision || '').trim()
  );
}

function isProcessTerminal(value) {
  const status = String(value?.status || '').toUpperCase();
  return ['AWAITING_CONFIRMATION', 'NEEDS_RETAKE', 'COMPLETED'].includes(status);
}

function saveProcessFinal(jobId, payload) {
  const merged = {
    ...(store.jobs[jobId] || {}),
    ...payload,
    job_id: jobId,
    worker_final: true,
    worker_final_at: nowIso,
    updated_at: nowIso,
  };
  store.jobs[jobId] = merged;
  store.processFinals[jobId] = { ...merged };
  task.final_result = { ...merged };
  task.final_result_at = now;
  return merged;
}

// Idempotent repair path. A worker may retry a final callback after losing the
// HTTP response. The previous workflow returned early for completed tasks and
// could therefore discard the richer final linked payload. Always accept a
// duplicate final PROCESS result as a repair snapshot.
if (task.status === 'COMPLETED' || task.status === 'ERROR') {
  if (taskType === 'PROCESS' && ok && final && Object.keys(result).length) {
    const repaired = saveProcessFinal(task.job_id, result);
    return [{ json: {
      ok: true,
      task_id: taskId,
      final: true,
      duplicate: true,
      repaired: true,
      status: repaired.status || '',
      has_decision: hasDecisionPayload(repaired),
    } }];
  }
  return [{ json: { ok: true, task_id: taskId, final: true, duplicate: true } }];
}

const reportingWorker = String(body.worker_id || '');
const registeredWorker = String(store.worker.worker_id || '');
const ownsLease = String(task.leased_by || '') === reportingWorker;
const canRecoverStaleLease = Boolean(reportingWorker)
  && reportingWorker === registeredWorker
  && ['QUEUED', 'LEASED'].includes(String(task.status || '').toUpperCase());
if (!ownsLease && !canRecoverStaleLease) {
  return [{ json: { ok: false, detail: 'Task lease does not belong to this worker.' } }];
}

if (canRecoverStaleLease) {
  task.status = 'LEASED';
  task.leased_by = reportingWorker;
}
task.updated_at = now;
task.leased_at = now;

if (taskType === 'PRESIGN') {
  if (ok && final) {
    store.requests[task.job_id] = {
      ...(store.requests[task.job_id] || {}),
      ...result,
      request_id: task.job_id,
      job_id: task.job_id,
      inference_mode: String(task.payload?.inference_mode || 'AUTO').toUpperCase(),
      status: 'READY',
      updated_at: nowIso,
    };
  }
  if (!ok && final) {
    store.requests[task.job_id] = {
      request_id: task.job_id,
      job_id: task.job_id,
      status: 'ERROR',
      error,
      detail: error,
      updated_at: nowIso,
    };
  }
}

if (taskType === 'PROCESS') {
  if (ok && final) {
    // Final linked state from /jobs/{id}/links is authoritative. Keep a second
    // durable snapshot so bakery-job-status can recover if a stale lightweight
    // progress object is visible in store.jobs.
    saveProcessFinal(task.job_id, result);
  } else if (ok) {
    const existingFinal = store.processFinals[task.job_id];
    const current = store.jobs[task.job_id] || {};
    const currentIsRichTerminal = isProcessTerminal(current) && hasDecisionPayload(current);

    // Never let a late/partial progress callback downgrade a rich terminal state.
    if (!existingFinal && !currentIsRichTerminal) {
      store.jobs[task.job_id] = {
        ...current,
        ...result,
        job_id: task.job_id,
        updated_at: nowIso,
      };
    }
  }

  if (!ok && final) {
    store.jobs[task.job_id] = {
      ...(store.jobs[task.job_id] || {}),
      ...result,
      job_id: task.job_id,
      status: 'ERROR',
      error,
      updated_at: nowIso,
    };
    delete store.processFinals[task.job_id];
  }
}

if (taskType === 'CONFIRM') {
  if (ok) {
    store.jobs[task.job_id] = {
      ...(store.jobs[task.job_id] || {}),
      ...result,
      job_id: task.job_id,
      confirmation_error: '',
      updated_at: nowIso,
    };
    if (final && String(result.status || '').toUpperCase() === 'COMPLETED') {
      delete store.processFinals[task.job_id];
    }
  }
  if (!ok && final) {
    store.jobs[task.job_id] = {
      ...(store.jobs[task.job_id] || {}),
      job_id: task.job_id,
      status: 'CONFIRMING',
      confirmation_error: error || 'Confirmation failed.',
      error: '',
      updated_at: nowIso,
    };
  }
}

if (taskType === 'DEVELOPER_SETTINGS') {
  store.developerRequests[task.job_id] = ok && final
    ? {
        ...(store.developerRequests[task.job_id] || {}),
        ...result,
        request_id: task.job_id,
        status: 'COMPLETED',
        updated_at: nowIso,
      }
    : {
        ...(store.developerRequests[task.job_id] || {}),
        request_id: task.job_id,
        status: final ? 'ERROR' : 'PROCESSING',
        error,
        detail: error,
        updated_at: nowIso,
      };
  if (final && task.payload) delete task.payload.developer_key;
}

if (final) {
  task.status = ok ? 'COMPLETED' : 'ERROR';
  store.queue = store.queue.filter(id => id !== taskId);
}

return [{ json: {
  ok: true,
  task_id: taskId,
  final,
  process_final_saved: taskType === 'PROCESS' && ok && final,
  has_decision: taskType === 'PROCESS' && ok && final ? hasDecisionPayload(store.jobs[task.job_id]) : undefined,
} }];

const store = $getWorkflowStaticData('global');
const body = $json.body || {};
const now = Date.now();
const previousWorkerId = String(store.worker?.worker_id || '');
const currentWorkerId = String(body.worker_id || '');

// If a new worker process replaces the previous one, return only the old
// worker's leased tasks to the queue. Keep heartbeat itself lightweight.
if (previousWorkerId && currentWorkerId && previousWorkerId !== currentWorkerId) {
  store.tasks = store.tasks || {};
  for (const task of Object.values(store.tasks)) {
    if (
      String(task.status || '').toUpperCase() === 'LEASED'
      && String(task.leased_by || '') === previousWorkerId
    ) {
      task.status = 'QUEUED';
      task.leased_by = '';
      task.leased_at = 0;
      task.updated_at = now;
    }
  }
}

// Preserve any fields from the previous snapshot if an older worker omits
// them, while refreshing the authoritative liveness timestamp.
store.worker = {
  ...(store.worker || {}),
  ...body,
  worker_id: currentWorkerId,
  last_seen_ms: now,
  last_seen: new Date(now).toISOString(),
};

// IMPORTANT: cleanup is intentionally NOT performed in the heartbeat route.
// The old workflow could do a large hourly sweep here, making a liveness call
// slow or fail under load. Maintenance now runs only while Worker Next is idle.
return [{
  json: {
    ok: true,
    worker_id: currentWorkerId,
    last_seen: store.worker.last_seen,
  },
}];

const store = $getWorkflowStaticData('global');
const worker = store.worker || {};
// Heartbeat defaults to 10 s. Allow a few missed beats / transient proxy 503s
// before declaring the worker offline.
const online = Number(worker.last_seen_ms || 0) + 45000 > Date.now();
return [{ json: {
  ready: online && worker.ready === true && worker.r2_configured === true,
  orchestration: 'n8n-outbound-worker',
  worker_online: online,
  worker_id: worker.worker_id || null,
  worker_last_seen: worker.last_seen || null,
  r2_configured: worker.r2_configured === true,
  kiotviet_configured: worker.kiotviet_configured === true,
  manufacturing_configured: worker.manufacturing_configured === true,
  kiotviet_auto_create_draft: worker.kiotviet_auto_create_draft === true,
  model: worker.model || null,
  max_images_per_job: Math.max(1, Number(worker.max_images_per_job || 50)),
  max_image_size_mb: worker.max_image_size_mb || 50,
  max_job_upload_size_mb: worker.max_job_upload_size_mb || 50,
  allowed_image_extensions: worker.allowed_image_extensions || ['.jpg', '.jpeg', '.png', '.webp', '.bmp'],
  error: online ? '' : 'Outbound AI worker is offline.',
} }];

